-- GENERATED from the tenant mapping (version 0b9e11683ec9dc1d). Do not edit.
SELECT DISTINCT  -- account.main
    (a.loan_id) AS account_key,
    (a.loan_number) AS account_number,
    CASE (a.product_code) WHEN 'HL' THEN 'HOUSING_LOAN' WHEN 'LAP' THEN 'PROPERTY_LOAN' WHEN 'PL' THEN 'PERSONAL_LOAN' WHEN 'AL' THEN 'AUTO_LOAN' WHEN 'UCL' THEN 'USED_CAR_LOAN' WHEN 'TWL' THEN 'TWO_WHEELER_LOAN' WHEN 'CVL' THEN 'COMMERCIAL_VEHICLE_LOAN' WHEN 'GL' THEN 'GOLD_LOAN' WHEN 'EDU' THEN 'EDUCATION_LOAN' WHEN 'CDL' THEN 'CONSUMER_LOAN' WHEN 'BLU' THEN 'BUSINESS_LOAN_UNSECURED' WHEN 'BLS' THEN 'BUSINESS_LOAN_SECURED' WHEN 'MFP' THEN 'MICROFINANCE_PERSONAL_LOAN' WHEN 'MFB' THEN 'MICROFINANCE_BUSINESS_LOAN' WHEN 'KCC' THEN 'KISAN_CREDIT_CARD' WHEN 'LAS' THEN 'LOAN_AGAINST_SHARES_SECURITIES' WHEN 'LOC' THEN 'LOAN_ON_CREDIT_CARD' WHEN 'CC' THEN 'CREDIT_CARD' WHEN 'SCC' THEN 'SECURED_CREDIT_CARD' WHEN 'CCC' THEN 'CORPORATE_CREDIT_CARD' WHEN 'FLC' THEN 'FLEET_CARD' WHEN 'OD' THEN 'OVERDRAFT' ELSE (a.product_code) END AS account_type,
    (a.disbursement_date) AS date_opened,
    (a.last_payment_date) AS date_last_payment,
    (a.closed_date) AS date_closed,
    (a.reported_date) AS date_reported,
    (a.sanction_amount) AS high_credit_amount,
    (a.outstanding_amount) AS current_balance,
    (a.overdue_amount) AS amount_overdue,
    (a.days_past_due) AS days_past_due,
    CASE (a.suit_status) WHEN 'NONE' THEN 'NO_SUIT_FILED' WHEN 'SUIT_FILED' THEN 'SUIT_FILED' WHEN 'WILFUL' THEN 'WILFUL_DEFAULT' WHEN 'SUIT_WILFUL' THEN 'SUIT_FILED_WILFUL_DEFAULT' ELSE (a.suit_status) END AS suit_filed_status,
    CASE (a.facility_status) WHEN 'RESTRUCT_COVID' THEN 'RESTRUCTURED_DUE_TO_COVID_19' WHEN 'WRITTEN_OFF' THEN 'WRITTEN_OFF' WHEN 'SETTLED' THEN 'SETTLED' WHEN 'POST_WO_SETTLED' THEN 'POST_WO_SETTLED' WHEN 'AUCTIONED_SETTLED' THEN 'AUCTIONED_SETTLED' WHEN 'REPOSSESSED_SETTLED' THEN 'REPOSSESSED_SETTLED' WHEN 'GUARANTEE_INVOKED' THEN 'GUARANTEE_INVOKED' ELSE (a.facility_status) END AS credit_facility_status,
    CASE (a.asset_classification) WHEN 'STD' THEN 'STANDARD' WHEN 'SUB' THEN 'SUBSTANDARD' WHEN 'DBT' THEN 'DOUBTFUL' WHEN 'LOSS' THEN 'LOSS' WHEN 'SMA' THEN 'SPECIAL_MENTION_ACCOUNT' ELSE (a.asset_classification) END AS asset_classification,
    (a.collateral_value) AS collateral_value,
    CASE (a.collateral_type) WHEN 'NONE' THEN 'NONE' WHEN 'PROPERTY' THEN 'PROPERTY' WHEN 'GOLD' THEN 'GOLD' WHEN 'SHARES' THEN 'SHARES' WHEN 'DEPOSIT' THEN 'SAVINGS_ACCOUNT_FD' WHEN 'MULTIPLE' THEN 'MULTIPLE_SECURITIES' WHEN 'OTHER' THEN 'OTHERS' ELSE (a.collateral_type) END AS collateral_type,
    (a.credit_limit) AS credit_limit,
    (a.cash_limit) AS cash_limit,
    (a.interest_rate_percent) AS rate_of_interest,
    (a.tenure_months) AS repayment_tenure,
    (a.emi_amount) AS emi_amount,
    (a.writeoff_total_amount) AS written_off_total,
    (a.writeoff_principal_amount) AS written_off_principal,
    (a.settlement_amount) AS settlement_amount,
    CASE (a.pay_frequency) WHEN 'WEEKLY' THEN 'WEEKLY' WHEN 'FORTNIGHTLY' THEN 'FORTNIGHTLY' WHEN 'MONTHLY' THEN 'MONTHLY' WHEN 'QUARTERLY' THEN 'QUARTERLY' WHEN 'BULLET' THEN 'BULLET' WHEN 'DAILY' THEN 'DAILY' WHEN 'HALFYEARLY' THEN 'HALF_YEARLY' WHEN 'YEARLY' THEN 'YEARLY' WHEN 'ONDEMAND' THEN 'ON_DEMAND' ELSE (a.pay_frequency) END AS payment_frequency,
    (a.last_payment_amount) AS actual_payment_amount,
    (a.previous_member_code) AS old_member_code,
    (a.previous_member_short_name) AS old_member_short_name,
    (a.previous_loan_number) AS old_account_number,
    CASE (a.previous_product_code) WHEN 'HL' THEN 'HOUSING_LOAN' WHEN 'LAP' THEN 'PROPERTY_LOAN' WHEN 'PL' THEN 'PERSONAL_LOAN' WHEN 'AL' THEN 'AUTO_LOAN' WHEN 'UCL' THEN 'USED_CAR_LOAN' WHEN 'TWL' THEN 'TWO_WHEELER_LOAN' WHEN 'CVL' THEN 'COMMERCIAL_VEHICLE_LOAN' WHEN 'GL' THEN 'GOLD_LOAN' WHEN 'EDU' THEN 'EDUCATION_LOAN' WHEN 'CDL' THEN 'CONSUMER_LOAN' WHEN 'BLU' THEN 'BUSINESS_LOAN_UNSECURED' WHEN 'BLS' THEN 'BUSINESS_LOAN_SECURED' WHEN 'MFP' THEN 'MICROFINANCE_PERSONAL_LOAN' WHEN 'MFB' THEN 'MICROFINANCE_BUSINESS_LOAN' WHEN 'KCC' THEN 'KISAN_CREDIT_CARD' WHEN 'LAS' THEN 'LOAN_AGAINST_SHARES_SECURITIES' WHEN 'LOC' THEN 'LOAN_ON_CREDIT_CARD' WHEN 'CC' THEN 'CREDIT_CARD' WHEN 'SCC' THEN 'SECURED_CREDIT_CARD' WHEN 'CCC' THEN 'CORPORATE_CREDIT_CARD' WHEN 'FLC' THEN 'FLEET_CARD' WHEN 'OD' THEN 'OVERDRAFT' ELSE (a.previous_product_code) END AS old_account_type,
    CASE (a.previous_party_role) WHEN 'PRIMARY' THEN 'INDIVIDUAL' WHEN 'ADDON' THEN 'AUTHORISED_USER' WHEN 'GUARANTOR' THEN 'GUARANTOR' WHEN 'JOINT' THEN 'JOINT' WHEN 'DECEASED' THEN 'DECEASED' ELSE (a.previous_party_role) END AS old_ownership_indicator
FROM nbfc_001.account_details a
WHERE a.disbursement_date <= :as_of_date;
